      if (/^(core competencies|key skills|skills|technical skills|skills \/ training|skills and training|computer proficiency|skill set|professional skills|strengths|areas of expertise)$/.test(h)) return 'skills';
      if (/^(education|academic qualification|academic qualifications|education and qualifications|educational background)$/.test(h)) return 'education';
      if (/^(certifications|certification|training|courses)$/.test(h)) return 'certifications';
